INSERT INTO picture360_images (examId, specialty, conditionName, imageUrl, keyFeatures, examPearl, optionA, optionB, optionC, optionD, correctAnswer, explanation, status) VALUES
(1, 'Chest X-ray', 'Bronchiectasis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_bronchiectasis-placeholder.webp', 'Tram-track sign (parallel lines representing thickened bronchial walls); ring shadows (dilated bronchi seen end-on); signet ring sign on CT (dilated bronchus larger than adjacent pulmonary artery); may show volume loss and crowding of bronchi', 'Bronchiectasis is permanent dilatation of the bronchi. Common causes: post-infectious (most common worldwide), cystic fibrosis (most common in children), primary ciliary dyskinesia, allergic bronchopulmonary aspergillosis, immunodeficiency. HRCT is the gold standard investigation. Treatment includes airway clearance physiotherapy and prompt treatment of exacerbations', 'Permanent bronchial dilatation with tram-track and ring shadow signs', 'COPD with hyperinflation', 'Pulmonary fibrosis', 'Lung abscess', 'A', 'Bronchiectasis is irreversible dilatation of the bronchi. Chest X-ray may show tram-track lines (thickened bronchial walls) and ring shadows (dilated bronchi seen end-on). HRCT is the gold standard, showing the signet ring sign. Common causes include post-infectious damage, cystic fibrosis, primary ciliary dyskinesia, and ABPA. Management includes airway clearance physiotherapy, prompt antibiotic treatment of exacerbations, and treatment of the underlying cause.', 'active'),
(1, 'Chest X-ray', 'Aspiration Pneumonia', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_aspiration-pneumonia-placeholder.webp', 'Consolidation in dependent lung segments: right lower lobe (upright aspiration) or posterior segments of upper lobes and superior segments of lower lobes (supine aspiration); may be bilateral; air bronchograms within consolidation', 'Aspiration pneumonia affects dependent lung segments. In upright patients, the right lower lobe is most commonly affected (the right main bronchus is wider, shorter, and more vertical). In supine patients, the posterior segments of the upper lobes and superior segments of the lower lobes are affected. Risk factors include reduced consciousness, dysphagia, GORD, and poor dentition', 'Pneumonia in dependent segments from aspiration of oropharyngeal contents', 'Community-acquired lobar pneumonia', 'Pulmonary oedema', 'Pulmonary embolism with infarction', 'A', 'Aspiration pneumonia results from inhalation of oropharyngeal or gastric contents into the lungs. It characteristically affects dependent lung segments: the right lower lobe in upright patients (the right main bronchus is wider, shorter, and more vertical) and posterior segments in supine patients. Risk factors include reduced consciousness, dysphagia, stroke, GORD, and poor dentition. Treatment is antibiotics covering anaerobes (co-amoxiclav or piperacillin-tazobactam) and management of the underlying aspiration risk.', 'active'),
(1, 'Chest X-ray', 'Lung Abscess', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_lung-abscess-placeholder.webp', 'Thick-walled cavitating lesion with an air-fluid level; usually in the posterior segments of the upper lobes or superior segments of the lower lobes (aspiration-related); surrounding consolidation; may be solitary or multiple', 'Lung abscess is most commonly caused by aspiration of anaerobic organisms. Risk factors include poor dentition, alcoholism, reduced consciousness, and immunosuppression. Treatment is prolonged antibiotics (4-6 weeks of co-amoxiclav or clindamycin). Surgical drainage or resection is reserved for failure of medical therapy. Always exclude underlying malignancy with follow-up imaging', 'Cavitating pulmonary infection with air-fluid level', 'Cavitating lung carcinoma', 'Tuberculosis with cavitation', 'Pulmonary infarction', 'A', 'A lung abscess presents as a thick-walled cavitating lesion with an air-fluid level on chest X-ray. It is most commonly caused by aspiration of anaerobic organisms and typically affects dependent lung segments. Risk factors include poor dentition, alcoholism, and immunosuppression. Treatment is prolonged antibiotics (4-6 weeks). Percutaneous or surgical drainage is reserved for failure of medical therapy. Follow-up imaging is essential to exclude an underlying malignancy.', 'active'),
(1, 'Chest X-ray', 'Diaphragmatic Hernia', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_diaphragmatic-hernia-placeholder.webp', 'Gas-filled loops of bowel visible above the diaphragm in the thorax; usually left-sided; loss of the normal diaphragmatic contour; mediastinal shift to the contralateral side in large hernias; nasogastric tube may be seen curling into the thorax', 'Congenital diaphragmatic hernia (Bochdalek) is left-sided in 85% of cases and presents with respiratory distress at birth. In adults, traumatic diaphragmatic rupture is more common on the left (the liver protects the right). Hiatus hernia (through the oesophageal hiatus) is the most common type overall and may show a retrocardiac gas shadow', 'Herniation of abdominal contents through the diaphragm into the thorax', 'Elevated hemidiaphragm from phrenic nerve palsy', 'Pleural effusion', 'Lung collapse', 'A', 'Diaphragmatic hernia involves herniation of abdominal contents through the diaphragm into the thorax. Congenital diaphragmatic hernia (Bochdalek type) is left-sided in 85% of cases and presents with neonatal respiratory distress. In adults, traumatic rupture is more common on the left. Chest X-ray shows gas-filled bowel loops above the diaphragm with loss of the diaphragmatic contour. A nasogastric tube curling into the thorax is diagnostic. Treatment is surgical repair.', 'active'),
(1, 'Chest X-ray', 'Aortic Aneurysm', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_aortic-aneurysm-placeholder.webp', 'Widened mediastinum; enlarged aortic knuckle; tracheal deviation to the right; left-sided pleural effusion (haemothorax if ruptured); calcification of the aortic wall may be visible; loss of the aortopulmonary window', 'A widened mediastinum on chest X-ray should raise suspicion of thoracic aortic aneurysm or dissection. CT aortogram is the definitive investigation. Risk factors include hypertension, atherosclerosis, Marfan syndrome, Ehlers-Danlos syndrome, and bicuspid aortic valve. Elective repair is considered when the ascending aorta exceeds 5.5cm (5.0cm in Marfan syndrome)', 'Thoracic aortic dilatation causing mediastinal widening', 'Mediastinal lymphadenopathy', 'Mediastinal mass or tumour', 'Normal variant wide mediastinum', 'A', 'Thoracic aortic aneurysm may present on chest X-ray as a widened mediastinum, enlarged aortic knuckle, tracheal deviation, and loss of the aortopulmonary window. CT aortogram is the definitive investigation. Risk factors include hypertension, atherosclerosis, connective tissue disorders (Marfan, Ehlers-Danlos), and bicuspid aortic valve. Elective surgical repair is considered when the ascending aorta exceeds 5.5cm. Acute rupture or dissection presents with sudden severe chest pain and haemodynamic instability.', 'active'),
(1, 'Chest X-ray', 'Mediastinal Widening', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_mediastinal-widening-placeholder.webp', 'Mediastinum wider than 8cm on PA chest X-ray; loss of normal mediastinal contours; may be caused by aortic pathology, lymphadenopathy, mediastinal mass, or technical factors (AP film, rotation, expiration)', 'Always check if the film is AP or PA before diagnosing mediastinal widening — AP films magnify the mediastinum. Causes include aortic aneurysm or dissection, lymphoma, thymoma, retrosternal goitre, and mediastinal haemorrhage (trauma). In trauma, a widened mediastinum suggests aortic injury until proven otherwise', 'Widened mediastinum requiring investigation for aortic or mass pathology', 'Normal AP chest X-ray appearance', 'Pericardial effusion', 'Cardiomegaly', 'A', 'Mediastinal widening on chest X-ray (greater than 8cm on PA film) has multiple causes. Always confirm the film is PA, as AP films magnify the mediastinum. Important causes include aortic aneurysm or dissection, lymphoma (most common cause of anterior mediastinal mass in young adults), thymoma, retrosternal goitre, and mediastinal haemorrhage. In trauma, a widened mediastinum suggests aortic injury until proven otherwise with CT aortogram. Further investigation depends on clinical context.', 'active'),
(1, 'Chest X-ray', 'Atelectasis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_atelectasis-placeholder.webp', 'Volume loss with displacement of fissures toward the collapsed lobe; ipsilateral mediastinal shift; ipsilateral hemidiaphragm elevation; compensatory hyperinflation of adjacent lobes; increased density of the collapsed lobe', 'Each lobe has a characteristic collapse pattern. Left lower lobe collapse causes a triangular density behind the heart (sail sign). Right middle lobe collapse causes loss of the right heart border. Right upper lobe collapse causes elevation of the right hilum. Always consider an obstructing endobronchial lesion (carcinoma) as the cause of lobar collapse in adults', 'Lung volume loss from airway obstruction or compression', 'Pleural effusion', 'Consolidation from pneumonia', 'Pneumothorax', 'A', 'Atelectasis (lung collapse) results from loss of lung volume due to airway obstruction, external compression, or surfactant loss. Chest X-ray shows increased density of the collapsed lobe, displacement of fissures, ipsilateral mediastinal shift, and hemidiaphragm elevation. Each lobe has a characteristic collapse pattern. In adults, an obstructing endobronchial lesion (bronchial carcinoma) must be excluded as the cause. Post-operative atelectasis is common and managed with physiotherapy and incentive spirometry.', 'active'),
(1, 'Chest X-ray', 'Foreign Body Inhalation', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_foreign-body-placeholder.webp', 'Unilateral hyperinflation due to ball-valve obstruction (air trapping); mediastinal shift away from the affected side on expiration; the foreign body itself may be visible if radio-opaque; right main bronchus is more commonly affected; segmental or lobar collapse if complete obstruction', 'Foreign body aspiration is most common in children aged 1-3 years. The right main bronchus is more commonly affected (wider, shorter, more vertical). Inspiratory and expiratory films help demonstrate air trapping. Rigid bronchoscopy is both diagnostic and therapeutic. Peanuts are the most commonly aspirated foreign body in children', 'Inhaled foreign body causing unilateral air trapping or collapse', 'Pneumothorax', 'Congenital lobar emphysema', 'Bronchial asthma', 'A', 'Foreign body inhalation most commonly affects children aged 1-3 years. The right main bronchus is more frequently involved due to its wider diameter, shorter length, and more vertical orientation. Chest X-ray may show unilateral hyperinflation (ball-valve effect), mediastinal shift on expiratory films, or lobar collapse. The foreign body may be visible if radio-opaque. Inspiratory and expiratory films aid diagnosis. Rigid bronchoscopy is both diagnostic and therapeutic and should be performed urgently.', 'active'),
(1, 'Chest X-ray', 'Empyema', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_empyema-placeholder.webp', 'Loculated pleural effusion that does not shift with positioning; D-shaped opacity against the chest wall; air-fluid level within the pleural space if bronchopleural fistula present; associated consolidation in the adjacent lung; split pleura sign on contrast CT', 'Empyema is pus in the pleural space, usually complicating parapneumonic effusion. Diagnostic thoracentesis shows pH less than 7.2, glucose less than 2.2 mmol/L, and LDH greater than 1000 IU/L. Treatment is chest drain insertion with intrapleural fibrinolytics (alteplase and DNase). VATS may be needed for multiloculated collections', 'Infected pleural collection requiring drainage', 'Simple parapneumonic effusion', 'Lung abscess', 'Pleural mesothelioma', 'A', 'Empyema is a collection of pus in the pleural space, most commonly complicating pneumonia (parapneumonic empyema). Chest X-ray shows a loculated pleural effusion that does not shift with positioning. CT with contrast shows the split pleura sign. Diagnostic thoracentesis reveals pH less than 7.2, low glucose, high LDH, and positive culture. Treatment is IV antibiotics and chest drain insertion. Intrapleural fibrinolytics (alteplase and DNase) improve drainage. VATS is indicated for multiloculated collections.', 'active'),
(1, 'Chest X-ray', 'Pancoast Tumour', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/cxr_pancoast-placeholder.webp', 'Apical opacity or mass in the lung apex; may show rib destruction or erosion of the first or second rib; asymmetric apical cap; associated Horner syndrome (miosis, ptosis, anhidrosis) from involvement of the sympathetic chain; may cause hand weakness from brachial plexus invasion', 'Pancoast tumour (superior sulcus tumour) is a lung carcinoma at the apex invading local structures. Pancoast syndrome includes shoulder and arm pain (brachial plexus C8-T2), Horner syndrome (sympathetic chain), and rib destruction. It is easily missed on chest X-ray — always scrutinise the lung apices. MRI is the best imaging modality for assessing local invasion', 'Apical lung carcinoma invading the chest wall and brachial plexus', 'Tuberculosis with apical cavitation', 'Cervical rib', 'Mesothelioma', 'A', 'A Pancoast tumour is a lung carcinoma arising at the lung apex (superior sulcus). It invades local structures causing Pancoast syndrome: shoulder and arm pain from brachial plexus invasion (C8-T2), Horner syndrome from sympathetic chain involvement, and rib destruction. Chest X-ray shows an apical opacity or mass, which is easily overlooked. MRI is the best modality for assessing local invasion. Treatment depends on staging and may include chemoradiotherapy followed by surgical resection.', 'active');
